  "canonical_text": {
    "quote": "",
    "summary": "The passage presents three origin accounts: children on a sea cliff become guillemots after a cliff collapse; a man repeatedly saying the word for a deerskin blanket becomes a raven whose call preserves the sound; and the loon's white breast, square back spots, and hiding behavior are explained through painting, laughter, and shame.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Children are playing on the level top of a high cliff overhanging the sea while older children watch younger ones to keep them from falling.",
      "category": "setting",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "A crack opens in the sea ice and the water fills with seals; men move to launch kayaks to pursue them.",
      "category": "sequence",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "The children shout loudly, frightening the seals so that they dive out of sight.",
      "category": "action",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:4",
      "text": "One angry man says he wishes the cliff would topple over and bury the noisy children.",
      "category": "speech",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:5",
      "text": "Immediately after the angry speech, the cliff tips over and the children fall among rocks and stones below.",
      "category": "sequence",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:6",
      "text": "The fallen children are changed into guillemots or sea-pigeons with red feet, and they dwell among debris at the foot of sea cliffs.",
      "category": "sequence",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:7",
      "text": "The raven is described as formerly a man who told people moving camp that they had forgotten a lower deerskin blanket used for a bed.",
      "category": "action",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:8",
      "text": "The deerskin bed blanket is called kak in the Eskimo language, and the man uses the word repeatedly.",
      "category": "speech",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:9",
      "text": "After being told to get the blanket himself, the man hurries and is changed into a raven.",
      "category": "sequence",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:10",
      "text": "The raven is said to fly over moving camps and call “Kak! kak!” as a reminder not to forget the blanket.",
      "category": "speech",
      "evidence_refs": [
        "ev:7"
      ]
    },
    {
      "id": "obs:11",
      "text": "A man has two children whom he wishes might resemble each other.",
      "category": "relationship",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:12",
      "text": "The man paints one child, identified parenthetically as the loon, with a white breast and square spots on the back.",
      "category": "action",
      "evidence_refs": [
        "ev:8"
      ]
    },
    {
      "id": "obs:13",
      "text": "The other child, identified parenthetically as the raven, laughs at the loon’s appearance.",
      "category": "action",
      "evidence_refs": [
        "ev:9"
      ]
    },
    {
      "id": "obs:14",
      "text": "The loon becomes ashamed, escapes to the water, and presents its white breast to hide the spots on its back.",
      "category": "sequence",
      "evidence_refs": [
        "ev:9"
      ]
    }
